        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                nearest[i] = min(nearest[i], d / (r[i] + r[j]))
    total = 0.0
    weight = 0.0
    for i in range(n):
        if isfinite(nearest[i]) and occ[i] > 0:
            total += occ[i] * nearest[i]
            weight += occ[i]
