                nearest[i] = min(nearest[i], d / (r[i] + r[j]))
    weight = 0.0
    total = 0.0
    square = 0.0
    for i in range(n):
        if isfinite(nearest[i]) and occ[i] > 0:
            weight += occ[i]
            total += occ[i] * nearest[i]
            square += occ[i] * nearest[i] * nearest[i]
    if weight <= 0 or total <= 0:
        return 0.0
    mean = total / weight
    return sqrt(max(square / weight - mean * mean, 0.0)) / mean

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    en = [(p.get(a.get('element')) or {}).get('eneg') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf for a in sites]
    edges = s.get('neighbors') or []
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    field = [0.0 for a in sites]
    count = [0.0 for a in sites]
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and d <= 1.35 * nearest[i]:
            if en[i] is not None and en[j] is not None:
                field[i] += occ[j] * (en[j] - en[i])
                count[i] += occ[j]
    total = 0.0
    square = 0.0
    weight = 0.0
    for i in range(n):
        if count[i] > 0 and occ[i] > 0:
            value = field[i] / count[i]
            total += occ[i] * value
            square += occ[i] * value * value
            weight += occ[i]
    if weight <= 0:
        return 0.0
    return sqrt(max(square / weight - (total / weight) ** 2, 0.0))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    acceptor = [False for a in sites]
    for i in range(n):
        a = p.get(sites[i].get('element')) or {}
        g = a.get('group')
        en = a.get('eneg')
        acceptor[i] = (g is not None and 15 <= g <= 17) or (g == 14 and en is not None and en >= 2.3)
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf for a in sites]
    edges = s.get('neighbors') or []
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    weight = 0.0
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and d <= 1.35 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if acceptor[i] and acceptor[j]:
                total += w
    return total / weight if weight > 0 else 0.0
